import{_ as n,a0 as l,w as r,s as p,I as e,x as s,a1 as i,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 Fedora Linux 上安装 VLC | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 上安装 VLC | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 上安装 VLC | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 上安装 VLC | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210725 How to Install VLC on Fedora Linux","title":"如何在 Fedora Linux 上安装 VLC","tag":"202107","desc":""},"relativePath":"202107/20210725 How to Install VLC on Fedora Linux.md","filePath":"[post].md"}'),u={name:"202107/20210725 How to Install VLC on Fedora Linux.md"};function f(g,t,m,h,C,L){const a=l("Link");return r(),p("div",null,[t[18]||(t[18]=e("h1",{id:"如何在-fedora-linux-上安装-vlc",tabindex:"-1"},[s("如何在 Fedora Linux 上安装 VLC "),e("a",{class:"header-anchor",href:"#如何在-fedora-linux-上安装-vlc","aria-label":"Permalink to “如何在 Fedora Linux 上安装 VLC”"},"​")],-1)),t[19]||(t[19]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/31/215634thkmiihq1limel4i.jpg",alt:""})],-1)),t[20]||(t[20]=e("p",null,"如果你刚刚安装了 Fedora，现在想在上面安装你最喜欢的视频播放器 VLC，你可能不会在软件中心找到它。至少不会立即找到。",-1)),e("p",null,[t[1]||(t[1]=s("出于只有它的开发者知道的原因，Fedora 既没有安装 ",-1)),i(a,{href:"https://www.videolan.org/"},{default:o(()=>[...t[0]||(t[0]=[s("VLC",-1)])]),_:1}),t[2]||(t[2]=s("，也不包括在 Fedora 官方仓库中。",-1))]),t[21]||(t[21]=d('<p>那么，你如何在 Fedora 上安装 VLC 呢？很简单。RPM Fusion 是你的朋友。让我告诉你详细的步骤。</p><h3 id="在-fedora-linux-上安装-vlc" tabindex="-1">在 Fedora Linux 上安装 VLC <a class="header-anchor" href="#在-fedora-linux-上安装-vlc" aria-label="Permalink to “在 Fedora Linux 上安装 VLC”">​</a></h3><p>在这里使用命令行会更容易。你也可以使用图形化的方法。我将在后面讨论它。</p><p>打开终端，使用下面的命令来添加和启用包含 VLC 包的 RPM Fusion 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://mirrors.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>当被要求确认添加新仓库时按 <code>Y</code>。接下来，使用 DNF 命令安装 VLC：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install vlc</span></span></code></pre></div><p>它将在 Fedora 中从 RPM Fusion 仓库中安装 VLC，并从不同的仓库中安装一些额外的依赖项。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/07/installing-vlc-fedora-800x422.webp" alt="Installing VLC in Fedora with DNF command"></p><p>安装后，你可以在应用程序菜单中搜索 VLC，或者在“活动区”中搜索它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/vlc-fedora.png?resize=799%2C223&amp;ssl=1" alt="Search for VLC"></p><p>点击、启动并享受它。</p><h4 id="替代方法-从软件中心安装-vlc" tabindex="-1">替代方法：从软件中心安装 VLC <a class="header-anchor" href="#替代方法-从软件中心安装-vlc" aria-label="Permalink to “替代方法：从软件中心安装 VLC”">​</a></h4><p>当你已经启用了 RPM Fusion 仓库，你可以在软件中心显示这个仓库的应用。要做到这一点，在终端使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate core</span></span></code></pre></div><p>之后，打开软件中心，搜索 VLC 并从那里安装。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/07/vlc-in-fedora-software-center-800x486.webp" alt="VLC in Fedora software center"></p><p>如果你有添加 FlatHub 仓库，请避免安装 Flatpak 版本的 VLC，因为它的大小大约是 1GB。RPM 版本的大小要小得多。</p><p>我希望你觉得这个快速教程对在 Fedora 上安装 VLC 有帮助。享受吧。</p><hr>',20)),e("p",null,[t[4]||(t[4]=s("via: ",-1)),i(a,{href:"https://itsfoss.com/install-vlc-fedora/"},{default:o(()=>[...t[3]||(t[3]=[s("https://itsfoss.com/install-vlc-fedora/",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=s("作者：",-1)),i(a,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[5]||(t[5]=[s("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=s(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[6]||(t[6]=[s("lujun9972",-1)])]),_:1}),t[11]||(t[11]=s(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:o(()=>[...t[7]||(t[7]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[s("Linux中国",-1)])]),_:1}),t[17]||(t[17]=s(" 荣誉推出",-1))])])}const V=n(u,[["render",f]]);export{b as __pageData,V as default};
